#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    vector<int> a = {3, 1};  // a = 可追加元素的数组
    string b = "abc";  // b = 待修改的字符串
    int i = 1;  // i = 待修改位置
    a.push_back(4);
    b[i] = 'x';
    cout << a.size() << " " << b << endl;
    return 0;
}
